import ti_draw
import ti_system
imgs = [
    "",
    "",
    ""
]
cur_img = 0
while True:
    ti_draw.fill_rect(-1, -1, 321, 241)
    for w in range(64):
        for h in range(48):
            offset = (w * 48 + h) * 6

            nums = int(imgs[cur_img][offset:offset + 6], 16)

            ti_draw.set_color((nums >> 16) & 255, (nums >> 8) & 255, nums & 255)
            ti_draw.fill_rect(-1 + w * 5, -1 + h * 5, 6, 6)

    key = ti_system.wait_key()
    if(key == 25 or key == 26):
        cur_img += 1
        if(cur_img >= len(imgs)):
            cur_img = 0
    elif(key == 24 or key == 34):
        cur_img -= 1
        if(cur_img < 0):
            cur_img = len(imgs) - 1
